import React, { useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import './style.css';
import './phase1.css';
import './phase3.css';
import './phase5.css';

type Usage = { active_users: number; active_connectors: { by_type: Record<string, number> } };
type NavGroups = { workspace: boolean; platform: boolean };
type Connection = { connectionId: string; connectorType: string; status: string; agentId: string | null; lastJobState: string | null };
type Source = { id: string; type: string; name: string };
type Notification = { notificationId: string; type: string; summary: Record<string, unknown>; readAt: string | null };
type IdentifierField = { asset_id: string; field_name: string; entity_hint: string | null; format_pattern: string; detection: string; confidence: number; assertion_id: string | null };
type GraphView = { asset_ids: string[]; assets: Array<{ asset_id: string; qualified_name: string; asset_type: string; active: boolean }>; edges: Array<{ relationship_id: string; from_asset_id: string; to_asset_id: string; granularity: string }>; assertions: Array<{ assertion_id: string; relationship_id: string; evidence_method: string; review_status: string; verification: string; confidence_score: number | null; evidence_ids: string[]; explanation: string | null }>; gaps: Array<{ gap_id: string; reason: string }>; coverage: number; observable: boolean };
type GraphReport = { asset_id: string; name: string; tool: string | null; safe_path: string | null; lineage_assertions: number };
type GraphSnapshot = { snapshot_id: string; captured_at: string; event_cursor: number; asset_count: number };
type GraphAsset = { asset_id: string; qualified_name: string; asset_type: string; active: boolean };

function LineageWorkspace(props: { path: string; navigate: (path: string) => void }) {
  const [fields,setFields]=useState<IdentifierField[]>([]); const [lineage,setLineage]=useState<GraphView|null>(null);
  const [assets,setAssets]=useState<GraphAsset[]>([]);const [idPath,setIdPath]=useState<Array<{assetId:string;fieldName:string}>>([]);
  const [reports,setReports]=useState<GraphReport[]>([]); const [snapshots,setSnapshots]=useState<GraphSnapshot[]>([]);
  const [selected,setSelected]=useState(''); const [direction,setDirection]=useState<'both'|'upstream'|'downstream'>('both');
  const [value,setValue]=useState(''); const [matches,setMatches]=useState<Array<{asset_id:string;field_name:string;entity_hint:string|null;format_pattern:string}>>([]);
  const [fromSnapshot,setFromSnapshot]=useState(''); const [toSnapshot,setToSnapshot]=useState(''); const [changes,setChanges]=useState<Array<{event_type:string;asset_id:string|null}>>([]);
  const [message,setMessage]=useState(''); const [error,setError]=useState('');
  const selectedRef=useRef('');const lineageRequestRef=useRef(0);
  const view=props.path.startsWith('/bi-reports')?'reports':props.path.includes('/ids')?'ids':props.path.includes('/compare')?'compare':props.path.includes('/impact/')?'impact':'lineage';
  async function reload(){
    const requestId=++lineageRequestRef.current;
    const [identifierData,reportData,snapshotData,assetData]=await Promise.all([
      api<{fields:IdentifierField[]}>('/api/ids'),api<{reports:GraphReport[]}>('/api/reports'),api<{snapshots:GraphSnapshot[]}>('/api/lineage/snapshots'),api<{assets:GraphAsset[]}>('/api/lineage/assets'),
    ]);
    setFields(identifierData.fields);setReports(reportData.reports);setSnapshots(snapshotData.snapshots);setAssets(assetData.assets);
    const currentSelection=selectedRef.current||selected;
    const active=(currentSelection&&assetData.assets.some(asset=>asset.asset_id===currentSelection))?currentSelection:identifierData.fields[0]?.asset_id||assetData.assets[0]?.asset_id||'';
    if(active){selectedRef.current=active;setSelected(active);}
    if(active&&requestId===lineageRequestRef.current){const data=await api<GraphView>(`/api/lineage?assetId=${encodeURIComponent(active)}&direction=${direction}`);if(requestId===lineageRequestRef.current)setLineage(data);}
    if(identifierData.fields.some(field=>field.asset_id===active)){const path=await api<{fields:Array<{assetId:string;fieldName:string}>}>(`/api/ids/${active}/path`);if(requestId===lineageRequestRef.current)setIdPath(path.fields);}
    if(!fromSnapshot&&snapshotData.snapshots[0])setFromSnapshot(snapshotData.snapshots[0].snapshot_id);
    if(!toSnapshot&&snapshotData.snapshots.at(-1))setToSnapshot(snapshotData.snapshots.at(-1)!.snapshot_id);
  }
  useEffect(()=>{void reload().catch(reason=>setError(reason instanceof Error?reason.message:'Lineage could not be loaded.'));},[]);
  async function chooseAsset(assetId:string){selectedRef.current=assetId;setSelected(assetId);const requestId=++lineageRequestRef.current;try{const data=await api<GraphView>(`/api/lineage?assetId=${encodeURIComponent(assetId)}&direction=${direction}`);if(requestId===lineageRequestRef.current)setLineage(data);if(fields.some(field=>field.asset_id===assetId)){const path=await api<{fields:Array<{assetId:string;fieldName:string}>}>(`/api/ids/${assetId}/path`);if(requestId===lineageRequestRef.current)setIdPath(path.fields);}}catch(reason){setError(reason instanceof Error?reason.message:'Lineage could not be loaded.');}}
  async function importGolden(sourceId:'golden-dbt'|'golden-tableau'|'golden-powerbi',fixtureKey:'dbt-manifest'|'tableau-reports'|'power-bi-reports'){setError('');setMessage('');try{
    const draft=await api<{connectionId:string}>('/api/metadata/connections',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({sourceId})});
    await api(`/api/metadata/connections/${draft.connectionId}/activate`,{method:'POST'});
    await api(`/api/metadata/import/${draft.connectionId}`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({fixtureKey})});
    await reload();setMessage('Synthetic lineage imported from the selected golden fixture.');
  }catch(reason){setError(reason instanceof Error?reason.message:'Synthetic metadata import failed.');}}
  async function trace(event:React.FormEvent){event.preventDefault();setError('');try{const result=await api<{matches:typeof matches}>(`/api/ids/${selected}/trace`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({value})});setMatches(result.matches);setMessage(result.matches.length?'Identifier match found.':'No matching fingerprint was found.');}catch(reason){setError(reason instanceof Error?reason.message:'Identifier trace failed.');}finally{setValue('');}}
  async function compare(){if(!fromSnapshot||!toSnapshot)return;try{const result=await api<{changes:typeof changes}>(`/api/lineage/snapshots/${fromSnapshot}/compare/${toSnapshot}`);setChanges(result.changes);}catch(reason){setError(reason instanceof Error?reason.message:'Snapshots could not be compared.');}}
  async function review(assertionId:string){try{await api(`/api/lineage/assertions/${assertionId}/review`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({status:'accepted'})});setMessage('Assertion accepted; its verification status is unchanged.');await reload();}catch(reason){setError(reason instanceof Error?reason.message:'Assertion review failed.');}}
  const label=(assetId:string)=>lineage?.assets.find(asset=>asset.asset_id===assetId)?.qualified_name??assetId;
  return <section className="phase3-workspace"><div className="page-heading"><div><p className="eyebrow">Governed metadata graph</p><h1>{view==='ids'?'ID trace':view==='impact'?'Impact analysis':view==='compare'?'Snapshot compare':view==='reports'?'BI reports':'Lineage workspace'}</h1></div></div>
    <nav className="phase3-tabs" aria-label="Lineage workspace views"><a href="/lineage" aria-current={view==='lineage'?'page':undefined} onClick={event=>{event.preventDefault();props.navigate('/lineage');}}>Lineage</a><a href="/lineage/ids" aria-current={view==='ids'?'page':undefined} onClick={event=>{event.preventDefault();const id=fields[0]?.asset_id;if(id)void chooseAsset(id);props.navigate('/lineage/ids');}}>ID trace</a><a href={selected?`/lineage/impact/${selected}`:'/lineage'} aria-current={view==='impact'?'page':undefined} onClick={event=>{event.preventDefault();props.navigate(selected?`/lineage/impact/${selected}`:'/lineage');}}>Impact</a><a href="/lineage/compare" aria-current={view==='compare'?'page':undefined} onClick={event=>{event.preventDefault();props.navigate('/lineage/compare');}}>Snapshot compare</a><a href="/bi-reports" aria-current={view==='reports'?'page':undefined} onClick={event=>{event.preventDefault();props.navigate('/bi-reports');}}>BI reports</a></nav>
    <div className="phase3-toolbar"><label>{view==='ids'?'Identifier field':'Graph asset'}<select aria-label={view==='ids'?'Identifier field':'Graph asset'} value={selected} onChange={event=>void chooseAsset(event.target.value)}><option value="">Choose {view==='ids'?'a detected field':'an asset'}</option>{(view==='ids'?fields.map(field=>({asset_id:field.asset_id,label:`${field.entity_hint??'Identifier'} · ${field.field_name} · ${field.format_pattern}`})):assets.map(asset=>({asset_id:asset.asset_id,label:`${asset.qualified_name} · ${asset.asset_type}`}))).map(item=><option key={`${item.asset_id}-${item.label}`} value={item.asset_id}>{item.label}</option>)}</select></label>{view==='lineage'&&<label>Direction<select aria-label="Lineage direction" value={direction} onChange={event=>{const next=event.target.value as typeof direction;setDirection(next);if(selected){const requestId=++lineageRequestRef.current;void api<GraphView>(`/api/lineage?assetId=${encodeURIComponent(selected)}&direction=${next}`).then(data=>{if(requestId===lineageRequestRef.current)setLineage(data);});}}}><option value="both">Both directions</option><option value="upstream">Upstream</option><option value="downstream">Downstream</option></select></label>}{view==='lineage'&&<><button onClick={()=>void importGolden('golden-dbt','dbt-manifest')}>Import synthetic dbt manifest</button><button onClick={()=>void importGolden('golden-tableau','tableau-reports')}>Import synthetic Tableau reports</button><button onClick={()=>void importGolden('golden-powerbi','power-bi-reports')}>Import synthetic Power BI reports</button></>}</div>
    {error&&<p className="error" role="alert">{error}</p>}{message&&<p role="status">{message}</p>}
    {view==='lineage'&&<div className="lineage-layout"><article><h2>Data flow</h2>{lineage&&<><p>{Math.round(lineage.coverage*100)}% observed coverage · {lineage.gaps.length} documented gaps</p>{lineage.edges.length===0?<p>No lineage edges yet. Import the synthetic dbt manifest to load the golden graph.</p>:<ol className="lineage-edges">{lineage.edges.map(edge=><li key={edge.relationship_id}><span>{label(edge.from_asset_id)}</span><b aria-hidden="true">→</b><span>{label(edge.to_asset_id)}</span><small>{edge.granularity} · evidence-backed</small></li>)}</ol>}{lineage.gaps.map(gap=><p className="graph-gap" key={gap.gap_id}>Missing hop · {gap.reason}</p>)}</>}</article><article><h2>Assertions and evidence</h2>{lineage?.assertions.map(assertion=><div className="assertion-row" key={assertion.assertion_id}><p>{assertion.evidence_method} · {assertion.review_status}</p><p>Verification: {assertion.verification}</p><p>{assertion.evidence_ids.length} evidence item(s)</p>{assertion.review_status==='unreviewed'&&<button onClick={()=>void review(assertion.assertion_id)}>Accept assertion</button>}</div>)}</article></div>}
    {view==='ids'&&<article><h2>Identifier path</h2>{fields.length===0?<p>No identifier fields detected yet.</p>:<><p>Only field metadata and tenant-keyed fingerprints are stored. Lookup values are discarded after each request.</p><form onSubmit={event=>void trace(event)}><label>Value to trace<input aria-label="Value to trace" autoComplete="off" maxLength={256} value={value} onChange={event=>setValue(event.target.value)} /></label><button type="submit" disabled={!selected||!value}>Trace value</button></form>{matches.length>0?<ul>{matches.map(match=><li key={`${match.asset_id}-${match.field_name}`}>{match.entity_hint} · {match.field_name} · {match.format_pattern}</li>)}</ul>:null}<ol>{idPath.map(field=><li key={`${field.assetId}-${field.fieldName}`}>{field.fieldName} · probable identifier path</li>)}</ol></>}</article>}
    {view==='impact'&&<article><h2>Downstream impact</h2>{lineage?.gaps.map(gap=><p className="graph-gap" key={gap.gap_id}>Incomplete path · {gap.reason}</p>)}{reports.map(report=><p key={report.asset_id}>{report.name} · {report.tool??'BI'} · {report.lineage_assertions} linked flow(s)</p>)}</article>}
    {view==='compare'&&<article><h2>Graph changes</h2><div className="snapshot-selects"><label>Earlier snapshot<select aria-label="Earlier snapshot" value={fromSnapshot} onChange={event=>setFromSnapshot(event.target.value)}>{snapshots.map(snapshot=><option key={snapshot.snapshot_id} value={snapshot.snapshot_id}>{new Date(snapshot.captured_at).toLocaleString()} · {snapshot.asset_count} assets</option>)}</select></label><label>Later snapshot<select aria-label="Later snapshot" value={toSnapshot} onChange={event=>setToSnapshot(event.target.value)}>{snapshots.map(snapshot=><option key={snapshot.snapshot_id} value={snapshot.snapshot_id}>{new Date(snapshot.captured_at).toLocaleString()} · {snapshot.asset_count} assets</option>)}</select></label><button onClick={()=>void compare()}>Compare snapshots</button></div><ul>{changes.map((change,index)=><li key={`${change.event_type}-${change.asset_id}-${index}`}>{change.event_type} · {change.asset_id??'graph event'}</li>)}</ul>{snapshots.length===0&&<p>No graph snapshots have been captured.</p>}</article>}
    {view==='reports'&&<article><h2>Reports and lineage status</h2>{reports.map(report=><div className="report-row" key={report.asset_id}><div><strong>{report.name}</strong><p>{report.tool??'BI tool'} · {report.lineage_assertions} linked flow(s)</p></div>{report.safe_path&&<a href={report.safe_path} aria-label={`Open ${report.name}`}>Open report</a>}</div>)}{reports.length===0&&<p>No synthetic reports imported yet.</p>}</article>}
  </section>;
}

async function api<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, init);
  if (response.status === 401) throw new Error('unauthorized');
  if (!response.ok) {
    const result = await response.json().catch(() => ({})) as { error?: string };
    throw new Error(result.error ?? `request_failed_${response.status}`);
  }
  if (response.status === 204) return undefined as T;
  return response.json() as Promise<T>;
}

function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  async function submit(event: React.FormEvent) {
    event.preventDefault(); setError('');
    try {
      await api('/api/auth/login', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ email, password }) });
      location.assign('/');
    } catch { setError('Email or password is incorrect.'); }
  }
  return <main className="login"><form onSubmit={submit}><div className="brandmark">S</div><h1>Welcome to Scale Insyght</h1><p>Sign in to your workspace</p><label>Email<input autoComplete="username" type="email" required value={email} onChange={event => setEmail(event.target.value)} /></label><label>Password<input autoComplete="current-password" type="password" required value={password} onChange={event => setPassword(event.target.value)} /></label>{error && <p role="alert" className="error">{error}</p>}<button type="submit">Sign in</button><p className="muted">Single sign-on will be available in a later release.</p></form></main>;
}

function loadGroups(): NavGroups {
  try { return { workspace: localStorage.getItem('nav-workspace') !== 'false', platform: localStorage.getItem('nav-platform') !== 'false' }; }
  catch { return { workspace: true, platform: true }; }
}

function ConnectorsPage(props: { connections: Connection[]; reload: () => Promise<void>; navigate: (path: string) => void }) {
  const [sources, setSources] = useState<Source[]>([]);
  const [sourceId, setSourceId] = useState('');
  const [connectionId, setConnectionId] = useState('');
  const [stage, setStage] = useState<'closed' | 'choose' | 'scope' | 'complete'>('closed');
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  useEffect(() => { void api<{ sources: Source[] }>('/api/sources').then(result => setSources(result.sources)); }, []);

  async function createDraft() {
    setError(''); setMessage('');
    try {
      const created = await api<{ connectionId: string }>('/api/connections', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ sourceId }) });
      await api(`/api/connections/${created.connectionId}/test`, { method: 'POST' });
      setConnectionId(created.connectionId); setStage('scope');
    } catch (reason) { setError(reason instanceof Error ? reason.message : 'Connection test failed.'); }
  }

  async function activate() {
    setError('');
    try {
      const result = await api<{ profile: { profiled: number; listed: number; inaccessible: number } }>(`/api/connections/${connectionId}/activate`, {
        method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ scope: [] }),
      });
      setMessage(`Connector agent created. Profile complete: ${result.profile.profiled} objects profiled from ${result.profile.listed} listed; ${result.profile.inaccessible} inaccessible.`);
      setStage('complete'); await props.reload();
    } catch (reason) { setError(reason instanceof Error ? reason.message : 'Activation failed.'); }
  }

  return <section><div className="page-heading"><div><h1>Connectors</h1><p>Read-only sources and their connector agents.</p></div><button onClick={() => { setStage('choose'); setError(''); setMessage(''); }}>Add connector</button></div>
    {props.connections.length === 0 ? <p>No sources connected.</p> : <div className="cards">{props.connections.filter(connection => connection.status === 'active').map(connection => <article key={connection.connectionId}><span>{connection.connectorType.replaceAll('_', ' ')}</span><strong>{connection.agentId ? 'Connector agent active' : 'Connection active'}</strong><p>Last profile: {connection.lastJobState ?? 'Not started'}</p><button onClick={() => props.navigate(`/profile/${connection.connectionId}`)}>View profile</button><button onClick={() => props.navigate(`/dictionary?connection=${connection.connectionId}`)}>Open Dictionary</button><button onClick={() => props.navigate(`/er?connection=${connection.connectionId}`)}>Show ER diagram</button></article>)}</div>}
    {stage === 'choose' && <div className="modal" role="dialog" aria-modal="true" aria-labelledby="add-source-title"><div className="modal-card"><h2 id="add-source-title">Add a connector</h2><label>Source<select aria-label="Source" value={sourceId} onChange={event => setSourceId(event.target.value)}><option value="">Choose a synthetic source</option>{sources.map(source => <option key={source.id} value={source.id}>{source.name} ({source.type.replaceAll('_', ' ')})</option>)}</select></label><p>Only the synthetic golden dataset is available in this local demo.</p><div className="actions"><button onClick={() => setStage('closed')}>Cancel</button><button disabled={!sourceId} onClick={() => void createDraft()}>Test connection</button></div>{error && <p role="alert" className="error">{error}</p>}</div></div>}
    {stage === 'scope' && <div className="modal" role="dialog" aria-modal="true" aria-labelledby="scope-title"><div className="modal-card"><h2 id="scope-title">Choose scope</h2><p>Profile all discovered objects. Out-of-scope objects are never profiled, sampled, fingerprinted or queried.</p><label><input type="checkbox" defaultChecked /> Profile objects in the selected synthetic source</label><div className="actions"><button onClick={() => setStage('closed')}>Cancel</button><button onClick={() => void activate()}>Start profiling</button></div>{error && <p role="alert" className="error">{error}</p>}</div></div>}
    {stage === 'complete' && <div className="modal" role="dialog" aria-modal="true" aria-labelledby="complete-title"><div className="modal-card"><h2 id="complete-title">Discovery complete</h2><p role="status">{message}</p><div className="actions"><button onClick={() => setStage('closed')}>Close</button></div></div></div>}
  </section>;
}

function ProfilePage(props: { connectionId: string; navigate: (path: string) => void }) {
  const [profile, setProfile] = useState<Record<string, unknown> | null>(null);
  useEffect(() => { void api<{ profile: Record<string, unknown> | null }>(`/api/connections/${props.connectionId}/profile`).then(result => setProfile(result.profile)); }, [props.connectionId]);
  return <section><h1>Profile</h1>{profile ? <><p>Profiling complete</p><div className="cards"><article><span>Objects listed</span><strong>{String(profile.listed_count)}</strong></article><article><span>Tables profiled</span><strong>{String(profile.dataset_count)}</strong></article><article><span>Fields profiled</span><strong>{String(profile.field_count)}</strong></article><article><span>Inaccessible</span><strong>{String(profile.inaccessible_count)}</strong></article></div><div className="actions"><button onClick={() => props.navigate(`/dictionary?connection=${props.connectionId}`)}>Open Dictionary</button><button onClick={() => props.navigate(`/er?connection=${props.connectionId}`)}>Show ER diagram</button></div></> : <p>Profile is not available yet.</p>}</section>;
}

function DictionaryPage(props: { connectionId: string }) {
  const [tables, setTables] = useState<Array<{ asset_id: string; qualified_name: string; fields: Array<{ name: string; dataType: string; nullable: boolean; tags: string[] }> }>>([]);
  useEffect(() => { void api<{ tables: typeof tables }>(`/api/connections/${props.connectionId}/dictionary`).then(result => setTables(result.tables)); }, [props.connectionId]);
  return <section><h1>Dictionary</h1><p>Structural and statistical metadata only. No source rows are stored.</p><div className="dictionary-list">{tables.map(table => <details key={table.asset_id}><summary>{table.qualified_name}</summary><ul>{table.fields.map(field => <li key={field.name}><strong>{field.name.split('.').at(-1)}</strong> · {field.dataType}{field.nullable ? ' · nullable' : ''}{field.tags.length ? ` · ${field.tags.join(', ')}` : ''}</li>)}</ul></details>)}</div></section>;
}

function ControlsPage(props: { connectionId: string }) {
  const [scope, setScope] = useState<Array<{ qualifiedName: string; objectType: string; scopeMode: 'profile' | 'list_only' | 'exclude' }>>([]);
  const [saved, setSaved] = useState(false);
  const [tenantSettings,setTenantSettings]=useState({allowSelfApproval:false,timeZone:'Asia/Kolkata'});
  const [tenantSettingsSaved,setTenantSettingsSaved]=useState(false);
  useEffect(() => { void api<{ scope: typeof scope }>(`/api/connections/${props.connectionId}/scope`).then(result => setScope(result.scope)); }, [props.connectionId]);
  useEffect(()=>{void api<typeof tenantSettings>('/api/tenant/settings').then(setTenantSettings);},[]);
  async function save() { await api(`/api/connections/${props.connectionId}/scope`, { method: 'PUT', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ rules: scope }) }); setSaved(true); }
  async function saveTenantSettings(){await api('/api/tenant/settings',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(tenantSettings)});setTenantSettingsSaved(true);}
  return <section><h1>Controls</h1><p>Scope changes control which objects the next profile can inspect.</p><ul>{scope.map(rule => <li key={rule.qualifiedName}>{rule.qualifiedName} · {rule.scopeMode}</li>)}</ul><button onClick={() => void save()}>Save scope</button>{saved && <p role="status">Scope saved.</p>}<article><h2>Tenant settings</h2><label>Tenant time zone<input aria-label="Tenant time zone" value={tenantSettings.timeZone} onChange={event=>setTenantSettings({...tenantSettings,timeZone:event.target.value})} /></label><label><input type="checkbox" checked={tenantSettings.allowSelfApproval} onChange={event=>setTenantSettings({...tenantSettings,allowSelfApproval:event.target.checked})} />Allow self-approval</label><p>Off by default. If enabled, approvals by the definition owner are recorded as self-approved.</p><button onClick={()=>void saveTenantSettings()}>Save tenant settings</button>{tenantSettingsSaved&&<p role="status">Tenant settings saved.</p>}</article></section>;
}

function CatalogueQuestion() {
  const [question, setQuestion] = useState('');
  const [matches, setMatches] = useState<string[]>([]);
  const [error, setError] = useState('');
  async function search(event: React.FormEvent) {
    event.preventDefault(); setError('');
    try {
      const result = await api<{ matches: string[] }>(`/api/catalogue/search?q=${encodeURIComponent(question)}`);
      setMatches(result.matches);
    } catch (reason) { setError(reason instanceof Error ? reason.message : 'Search failed.'); }
  }
  return <div className="catalogue-question"><h2>Ask about your catalog</h2><p>Searches stored structural metadata without a model call.</p><form onSubmit={event => void search(event)}><label>Catalog question<input value={question} onChange={event => setQuestion(event.target.value)} placeholder="For example: which tables contain orders?" required /></label><button type="submit">Search catalog</button></form>{error && <p role="alert" className="error">{error}</p>}{matches.length > 0 && <ul aria-label="Catalog matches">{matches.map(match => <li key={match}>{match}</li>)}</ul>}{question && matches.length === 0 && <p role="status">No matching catalog objects.</p>}</div>;
}

type AnalyticRun = { runId: string; state: string; stateVersion:number; planHash?:string; plan: { question: string; steps: Array<{ source_id: string; agent_id: string }> }; answer: { answer: { claims?: Array<{ statement: string; evidence_ids: string[] }>; evidence?: Array<{ evidence_id: string; locator: string; redacted_summary: string }>; bySource?: Array<{ value: number; sourceId?: string }> }; presentation: { title: string; layout: string } } | null };

function AnalyticWorkspace(props: { connections: Connection[]; navigate: (path: string) => void; runId?:string|undefined }) {
  const [question,setQuestion]=useState('');const [selected,setSelected]=useState<string[]>([]);const [authorized,setAuthorized]=useState<string[]>([]);const [run,setRun]=useState<AnalyticRun|null>(null);const [events,setEvents]=useState<Array<{sequence:number;event_type:string}>>([]);const [error,setError]=useState('');const [feedback,setFeedback]=useState('');
  const active=props.connections.filter(item=>item.status==='active'&&authorized.includes(item.connectionId));
  useEffect(()=>{void api<{sources:Array<{id:string}>}>('/api/analytic/sources').then(result=>{const ids=result.sources.map(item=>item.id);setAuthorized(ids);setSelected(ids);}).catch(()=>setError('Authorized sources could not be loaded.'));},[]);
  useEffect(()=>{if(props.runId)void api<AnalyticRun>(`/api/runs/${props.runId}`).then(setRun).catch(()=>setError('Saved run could not be loaded.'));},[props.runId]);
  useEffect(()=>{if(!run)return;const after=events.at(-1)?.sequence??0;void api<{events:Array<{sequence:number;event_type:string}>}>(`/api/runs/${run.runId}/events?after=${after}`).then(result=>{if(result.events.length)setEvents(previous=>[...previous,...result.events]);}).catch(()=>setError('Run events could not be resumed.'));},[run?.runId,run?.stateVersion]);
  useEffect(()=>{if(run&&!['COMPLETED','PARTIAL','FAILED','CANCELLED','POLICY_BLOCKED'].includes(run.state)){const timer=setTimeout(()=>{void api<AnalyticRun>(`/api/runs/${run.runId}`).then(setRun).catch(()=>setError('Run status could not be refreshed.'));},600);return()=>clearTimeout(timer);}},[run]);
  async function ask(event:React.FormEvent){event.preventDefault();setError('');setFeedback('');try{const result=await api<{runId:string}>('/api/runs',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({question,sourceIds:selected})});props.navigate(`/runs/${result.runId}`);const detail=await api<AnalyticRun>(`/api/runs/${result.runId}`);setRun(detail);setEvents([]);}catch(reason){setError(reason instanceof Error?reason.message:'Question could not be started.');}}
  async function rate(verdict:'useful'|'not_useful'){if(!run)return;try{await api(`/api/runs/${run.runId}/feedback`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({verdict})});setFeedback('Feedback saved to your personal agent.');}catch(reason){setError(reason instanceof Error?reason.message:'Feedback could not be saved.');}}
  async function exportPack(format:'pdf'|'xlsx'|'pptx'){if(!run)return;try{const response=await fetch(`/api/runs/${run.runId}/evidence-pack`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({format})});if(!response.ok)throw new Error('Evidence pack could not be exported.');const blob=await response.blob();const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`evidence-${run.runId}.${format}`;link.click();URL.revokeObjectURL(link.href);}catch(reason){setError(reason instanceof Error?reason.message:'Evidence pack could not be exported.');}}
  return <section className="analytic-workspace"><div className="page-heading"><div><h1>What would you like to understand?</h1><p>Ask across your authorized synthetic sources. Analytic mode is read-only.</p></div><button onClick={()=>props.navigate('/agents')}>Agents</button></div>{!props.runId&&<form onSubmit={event=>void ask(event)}><label>Your question<textarea required value={question} onChange={event=>setQuestion(event.target.value)} placeholder="Compare the synthetic source totals" /></label><fieldset><legend>Sources</legend>{active.map(item=><label key={item.connectionId}><input type="checkbox" checked={selected.includes(item.connectionId)} onChange={event=>setSelected(old=>event.target.checked?[...old,item.connectionId]:old.filter(id=>id!==item.connectionId))}/>{item.connectorType.replaceAll('_',' ')}</label>)}</fieldset><button type="submit" disabled={!selected.length}>Ask question</button></form>}{active.length===0&&!props.runId&&<p>Connect a synthetic source to start an analytic run.</p>}{error&&<p role="alert" className="error">{error}</p>}{run&&<article aria-live="polite" className="run-card"><h2>Run {run.state.toLowerCase()}</h2><p>{run.plan.question}</p><h3>Validated plan</h3><ol>{run.plan.steps.map((step,index)=><li key={`${step.source_id}-${index}`}>Read authorized source · {step.source_id.slice(0,8)}</li>)}</ol><h3>Run progress</h3><ol>{events.map(item=><li key={item.sequence}>{item.event_type.replaceAll('_',' ')}</li>)}</ol>{run.answer&&<><h3>Answer: {run.answer.presentation.title}</h3>{run.answer.answer.claims?.map((claim,index)=><p key={index}>{claim.statement} <small>Evidence: {claim.evidence_ids.map(id=>run.answer?.answer.evidence?.find(item=>item.evidence_id===id)?.locator??id).join(', ')}</small></p>)}{run.answer.answer.bySource?.map((item,index)=><p key={index}>Synthetic result: {item.value}</p>)}<p><strong>Trust:</strong> evidence-backed · read-only</p>{run.state==='COMPLETED'&&<div className="export-actions" aria-label="Export evidence pack"><button onClick={()=>void exportPack('pdf')}>Export PDF</button><button onClick={()=>void exportPack('xlsx')}>Export Excel</button><button onClick={()=>void exportPack('pptx')}>Export PowerPoint</button></div>}<button onClick={()=>void rate('useful')}>Useful</button><button onClick={()=>void rate('not_useful')}>Not useful</button>{feedback&&<p role="status">{feedback}</p>}</>}</article>}{!props.runId&&<CatalogueQuestion/>}</section>;
}

function AgentGroups(){
  const [groups,setGroups]=useState<Array<{groupId:string;version:number;connectionId:string;connectorType:string}>>([]);const [target,setTarget]=useState<Record<string,string>>({});const [error,setError]=useState('');
  async function reload(){const result=await api<{groups:typeof groups}>('/api/agents');setGroups(result.groups);}
  useEffect(()=>{void reload().catch(()=>setError('Agent groups could not be loaded.'));},[]);
  const unique=[...new Map(groups.map(group=>[group.groupId,group])).values()];
  return <article><h2>Source groups</h2>{groups.map(group=><div key={group.connectionId}><span>{group.connectorType.replaceAll('_',' ')} · group {group.groupId.slice(0,8)} v{group.version}</span><label>Move to<select aria-label={`Move ${group.connectorType} source group`} value={target[group.connectionId]??''} onChange={event=>setTarget({...target,[group.connectionId]:event.target.value})}><option value="">Choose a group</option>{unique.filter(item=>item.groupId!==group.groupId).map(item=><option key={item.groupId} value={item.groupId}>{item.groupId.slice(0,8)} v{item.version}</option>)}</select></label><button disabled={!target[group.connectionId]} onClick={async()=>{try{await api(`/api/groups/${target[group.connectionId]}/members/${group.connectionId}`,{method:'POST'});await reload();}catch(reason){setError(reason instanceof Error?reason.message:'Group move failed.');}}}>Move source</button></div>)}{groups.length===0&&<p>No active source groups.</p>}{error&&<p role="alert">{error}</p>}</article>;
}

type GovernedReport = {reportId:string;name:string;governedId:string;version:number;latestSnapshotId:string|null;latestRunId:string|null;latestSnapshotAt:string|null};
function ReportsPage(){
  const [reports,setReports]=useState<GovernedReport[]>([]);const [governed,setGoverned]=useState<Array<{governedId:string;name:string;version:number;approvedBy:string|null}>>([]);const [schedules,setSchedules]=useState<Array<{scheduleId:string;reportId:string;localTime:string;cadence:'daily'|'weekly';weekday:number|null;timeZone:string;nextRunAt:string;enabled:boolean}>>([]);const [scheduleTimes,setScheduleTimes]=useState<Record<string,string>>({});const [cadences,setCadences]=useState<Record<string,'daily'|'weekly'>>({});const [weekdays,setWeekdays]=useState<Record<string,number>>({});const [name,setName]=useState('');const [governedVersion,setGovernedVersion]=useState('');const [localTime]=useState('06:00');const [message,setMessage]=useState('');const [error,setError]=useState('');
  async function reload(){const [reportData,agentData,scheduleData]=await Promise.all([api<{reports:GovernedReport[]}>('/api/me/reports'),api<{governed:typeof governed}>('/api/agents'),api<{schedules:typeof schedules}>('/api/me/schedules')]);setReports(reportData.reports);setGoverned(agentData.governed.filter(item=>item.approvedBy));setSchedules(scheduleData.schedules);}
  useEffect(()=>{void reload().catch(()=>setError('Reports could not be loaded.'));},[]);
  async function create(){const [governedId,version]=governedVersion.split(':');if(!governedId||!version)return;try{await api('/api/me/reports',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name,governedId,version:Number(version)})});setName('');setMessage('Governed report saved.');await reload();}catch(reason){setError(reason instanceof Error?reason.message:'Report could not be saved.');}}
  async function download(reportId:string,format:'pdf'|'xlsx'|'pptx'){try{const response=await fetch(`/api/me/reports/${reportId}/exports/${format}`);if(!response.ok)throw new Error((await response.json()).error??'Report export is not available yet.');const blob=await response.blob();const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`report.${format}`;link.click();URL.revokeObjectURL(link.href);}catch(reason){setError(reason instanceof Error?reason.message:'Report could not be exported.');}}
  return <section className="reports-page"><h1>Reports</h1><p>Governed reports use an approved definition version. Each run keeps its evidence snapshot.</p><article><h2>Create a governed report</h2><label>Report name<input value={name} onChange={event=>setName(event.target.value)} /></label><label>Approved definition<select value={governedVersion} onChange={event=>setGovernedVersion(event.target.value)}><option value="">Choose an approved version</option>{governed.map(item=><option key={`${item.governedId}:${item.version}`} value={`${item.governedId}:${item.version}`}>{item.name} · version {item.version}</option>)}</select></label><button disabled={!name.trim()||!governedVersion} onClick={()=>void create()}>Save report</button></article><article><h2>Governed reports</h2>{reports.map(report=>{const schedule=schedules.find(item=>item.reportId===report.reportId);const cadence=cadences[report.reportId]??schedule?.cadence??'daily';return <div className="report-card" key={report.reportId}><h3>{report.name}</h3><p>Approved version {report.version} · {report.latestSnapshotId?`Latest snapshot ${report.latestSnapshotId}`:'No completed run yet'}</p><div className="report-actions"><button onClick={async()=>{try{const result=await api<{runId:string}>(`/api/me/reports/${report.reportId}/run`,{method:'POST'});setMessage(`Report run ${result.runId} started.`);}catch(reason){setError(reason instanceof Error?reason.message:'Report run could not start.');}}}>Run report</button>{report.latestSnapshotId&&<><button onClick={()=>void download(report.reportId,'pdf')}>Download PDF</button><button onClick={()=>void download(report.reportId,'xlsx')}>Download Excel</button><button onClick={()=>void download(report.reportId,'pptx')}>Download PowerPoint</button></>}</div><label>Schedule cadence<select aria-label={`Schedule cadence for ${report.name}`} value={cadence} onChange={event=>setCadences({...cadences,[report.reportId]:event.target.value as 'daily'|'weekly'})}><option value="daily">Daily</option><option value="weekly">Weekly</option></select></label>{cadence==='weekly'&&<label>Weekday<select aria-label={`Schedule weekday for ${report.name}`} value={weekdays[report.reportId]??schedule?.weekday??1} onChange={event=>setWeekdays({...weekdays,[report.reportId]:Number(event.target.value)})}><option value={1}>Monday</option><option value={2}>Tuesday</option><option value={3}>Wednesday</option><option value={4}>Thursday</option><option value={5}>Friday</option><option value={6}>Saturday</option><option value={7}>Sunday</option></select></label>}<label>Local time<input aria-label={`Local schedule time for ${report.name}`} type="time" value={scheduleTimes[report.reportId]??schedule?.localTime??localTime} onChange={event=>setScheduleTimes({...scheduleTimes,[report.reportId]:event.target.value})} /></label><p>Times shown in the tenant time zone{schedule?.timeZone?` (${schedule.timeZone})`:''}; schedule instants are stored in UTC.</p><div className="report-actions"><button onClick={async()=>{try{await api('/api/me/schedules',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({reportId:report.reportId,localTime:scheduleTimes[report.reportId]??schedule?.localTime??localTime,cadence,...(cadence==='weekly'?{weekday:weekdays[report.reportId]??schedule?.weekday??1}:{})})});setMessage('Tenant-local schedule saved.');await reload();}catch(reason){setError(reason instanceof Error?reason.message:'Schedule could not be saved.');}}}>{schedule?.enabled?'Update schedule':'Save schedule'}</button>{schedule?.enabled&&<button onClick={async()=>{try{await api(`/api/me/schedules/${schedule.scheduleId}`,{method:'DELETE'});setMessage('Schedule disabled.');await reload();}catch(reason){setError(reason instanceof Error?reason.message:'Schedule could not be disabled.');}}}>Disable schedule</button>}</div></div>;})}{reports.length===0&&<p>No governed reports yet.</p>}</article>{error&&<p role="alert" className="error">{error}</p>}{message&&<p role="status">{message}</p>}</section>;
}

function AgentsPage(){
  const [memory,setMemory]=useState<{vocabulary:Record<string,string>;defaultSources:string[];answerStyle:string|null}>({vocabulary:{},defaultSources:[],answerStyle:'concise'});const [governed,setGoverned]=useState<Array<{governedId:string;name:string;version:number;approvedBy:string|null}>>([]);const [savedQuestions,setSavedQuestions]=useState<Array<{planId:string;question:string;createdAt:string}>>([]);const [name,setName]=useState('');const [question,setQuestion]=useState('');const [sources,setSources]=useState<string[]>([]);const [draft,setDraft]=useState<{governedId:string;version:number}|null>(null);const [message,setMessage]=useState('');const [error,setError]=useState('');
  async function loadGoverned(){const result=await api<{governed:typeof governed}>('/api/agents');setGoverned(result.governed);}
  async function loadSavedQuestions(){const result=await api<{questions:typeof savedQuestions}>('/api/me/saved-questions');setSavedQuestions(result.questions);}
  useEffect(()=>{void Promise.all([api<{memory:typeof memory}>('/api/me/agent'),api<{sources:Array<{id:string}>}>('/api/analytic/sources'),api<{governed:typeof governed}>('/api/agents'),api<{questions:typeof savedQuestions}>('/api/me/saved-questions')]).then(([saved,connected,agentData,questions])=>{setMemory(saved.memory);setSources(connected.sources.map(item=>item.id));setGoverned(agentData.governed);setSavedQuestions(questions.questions);}).catch(()=>setError('Agent settings could not be loaded.'));},[]);
  async function save(){try{const result=await api<{memory:typeof memory}>('/api/me/agent',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(memory)});setMemory(result.memory);setMessage('Personal agent settings saved.');}catch(reason){setError(reason instanceof Error?reason.message:'Settings could not be saved.');}}
  async function create(){try{const result=await api<{governedId:string;version:number}>('/api/governed-agents',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name,question,sourceIds:sources})});setDraft(result);setMessage(`Draft version ${result.version} saved. A different tenant member must approve it.`);await loadGoverned();}catch(reason){setError(reason instanceof Error?reason.message:'Draft could not be saved.');}}
  async function approve(){if(!draft)return;try{await api(`/api/governed-agents/${draft.governedId}/approve`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({version:draft.version})});setMessage(`Version ${draft.version} approved.`);}catch(reason){setError(reason instanceof Error?reason.message:'Approval requires a different member.');}}
  async function rerun(){if(!draft)return;try{const result=await api<{runId:string}>(`/api/governed-agents/${draft.governedId}/runs`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({version:draft.version})});setMessage(`Governed run ${result.runId} started.`);}catch(reason){setError(reason instanceof Error?reason.message:'Governed run could not be started.');}}
  return <section><h1>Agents</h1><p>Personal settings shape presentation only. Governed definitions are immutable by version.</p><AgentGroups/><article><h2>My agent</h2><label>Answer style<select value={memory.answerStyle??'concise'} onChange={event=>setMemory({...memory,answerStyle:event.target.value})}><option value="concise">Concise</option><option value="detailed">Detailed</option><option value="sql_first">SQL first</option><option value="lineage_first">Lineage first</option></select></label><label>Vocabulary term<input id="vocabulary-term" /></label><label>Meaning<input id="vocabulary-meaning" /></label><button onClick={()=>{const term=(document.getElementById('vocabulary-term') as HTMLInputElement).value;const meaning=(document.getElementById('vocabulary-meaning') as HTMLInputElement).value;if(term&&meaning){const updated={...memory,vocabulary:{...memory.vocabulary,[term]:meaning}};setMemory(updated);void api('/api/me/agent',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(updated)}).then(()=>setMessage('Personal agent settings saved.')).catch(()=>setError('Settings could not be saved.'));}else void save();}}>Save my agent</button><button onClick={async()=>{await api('/api/me/agent',{method:'DELETE'});setMemory({vocabulary:{},defaultSources:[],answerStyle:null});setSavedQuestions([]);setMessage('Personal memory deleted.');}}>Delete my memory</button><h3>Saved questions</h3><p>Saved only after you accepted the answer. Reuse one as the starting plan for another run.</p>{savedQuestions.map(item=><div className="saved-question" key={item.planId}><p>{item.question}</p><button onClick={async()=>{try{const result=await api<{runId:string}>(`/api/me/saved-questions/${item.planId}/start`,{method:'POST'});location.assign('/runs/'+result.runId);}catch(reason){setError(reason instanceof Error?reason.message:'Saved question could not be started.');}}}>Start from this plan</button><button onClick={async()=>{try{await api(`/api/me/saved-questions/${item.planId}`,{method:'DELETE'});await loadSavedQuestions();}catch(reason){setError(reason instanceof Error?reason.message:'Saved question could not be removed.');}}}>Remove</button></div>)}{savedQuestions.length===0&&<p>No saved questions yet.</p>}</article><article><h2>Governed definition</h2><label>Name<input value={name} onChange={event=>setName(event.target.value)} /></label><label>Question<input value={question} onChange={event=>setQuestion(event.target.value)} /></label><button disabled={!name||!question||!sources.length} onClick={()=>void create()}>Save draft version</button>{draft&&<><p>Draft {draft.governedId}, version {draft.version}</p><button onClick={()=>void approve()}>Approve version</button><button onClick={()=>void rerun()}>Run approved version</button></>}</article><article><h2>Saved governed versions</h2>{governed.map(item=><div key={`${item.governedId}-${item.version}`}><p>{item.name} · version {item.version} · {item.approvedBy?'Approved':'Awaiting approval'}</p>{item.approvedBy&&<button onClick={async()=>{try{const result=await api<{runId:string}>(`/api/governed-agents/${item.governedId}/runs`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({version:item.version})});setMessage(`Governed run ${result.runId} started.`);}catch(reason){setError(reason instanceof Error?reason.message:'Governed run could not be started.');}}}>Run version {item.version}</button>}</div>)}</article>{error&&<p role="alert" className="error">{error}</p>}{message&&<p role="status">{message}</p>}</section>;
}

function ApprovalMatrix() {
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [governed,setGoverned]=useState<Array<{governedId:string;name:string;ownerId:string;version:number;approvedBy:string|null}>>([]);const [evaluation,setEvaluation]=useState<{count:number;questionIds:string[]}>({count:0,questionIds:[]});const [message,setMessage]=useState('');
  const [flowspecs,setFlowspecs]=useState<Array<{flowspecId:string;latestVersion:number;subjectHash:string|null;approvalStatus:string|null}>>([]);
  const [assertions,setAssertions]=useState<Array<{assertion_id:string;from_name:string;to_name:string;evidence_method:string;review_status:string;verification:string;confidence_score:number|null;evidence_count:number}>>([]);
  async function refresh(){const [agentData,assertionData,flowData]=await Promise.all([api<{governed:typeof governed}>('/api/agents'),api<{assertions:typeof assertions}>('/api/lineage/assertions'),api<{flowspecs:typeof flowspecs}>('/api/flowspecs')]);setGoverned(agentData.governed);setAssertions(assertionData.assertions);setFlowspecs(flowData.flowspecs);void api<typeof evaluation>('/api/evaluation').then(setEvaluation).catch(()=>setEvaluation({count:0,questionIds:[]}));void api<{notifications:Notification[]}>('/api/notifications').then(result=>setNotifications(result.notifications)).catch(()=>setNotifications([]));}
  useEffect(() => { void refresh(); }, []);
  return <section><h1>Approval matrix</h1><p>Review evidence-backed lineage assertions separately from verification.</p><article><h2>Lineage assertions</h2>{assertions.map(item=><div className="assertion-row" key={item.assertion_id}><p>{item.from_name} → {item.to_name}</p><p>{item.evidence_method} · {item.review_status} · Verification: {item.verification} · {item.evidence_count} evidence item(s)</p>{item.review_status==='unreviewed'&&<button onClick={async()=>{try{await api(`/api/lineage/assertions/${item.assertion_id}/review`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({status:'accepted'})});setMessage('Assertion accepted; verification was not changed.');await refresh();}catch(reason){setMessage(reason instanceof Error?reason.message:'Review failed.');}}}>Accept assertion</button>}</div>)}{assertions.length===0&&<p>No assertions await review.</p>}</article><article><h2>FlowSpec approvals</h2>{flowspecs.map(item=><div key={item.flowspecId}><p>FlowSpec {item.flowspecId} · version {item.latestVersion} · {item.approvalStatus??'No approval'}</p>{item.approvalStatus==='pending'&&<button onClick={async()=>{try{await api(`/api/flowspecs/${item.flowspecId}/approve`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({version:item.latestVersion})});setMessage(`FlowSpec version ${item.latestVersion} approved.`);await refresh();}catch(reason){setMessage(reason instanceof Error?reason.message:'A different member must approve this FlowSpec.');}}}>Approve FlowSpec version {item.latestVersion}</button>}</div>)}{flowspecs.length===0&&<p>No FlowSpecs await review.</p>}</article><article><h2>Governed definitions</h2>{governed.map(item=><div key={`${item.governedId}-${item.version}`}><p>{item.name} · version {item.version} · {item.approvedBy?'Approved':'Awaiting approval'}</p>{!item.approvedBy&&<button onClick={async()=>{try{await api(`/api/governed-agents/${item.governedId}/approve`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({version:item.version})});setMessage(`Version ${item.version} approved.`);await refresh();}catch(reason){setMessage(reason instanceof Error?reason.message:'Approval failed.');}}}>Approve version {item.version}</button>}</div>)}{governed.length===0&&<p>No governed definitions yet.</p>}</article><article><h2>Evaluation set</h2><p>{evaluation.count} synthetic cases</p><ul>{evaluation.questionIds.map(id=><li key={id}>{id}</li>)}</ul></article><p role="status">{message}</p><h2>Notifications</h2>{notifications.length===0?<p>No findings yet.</p>:<ul>{notifications.map(item=><li key={item.notificationId}>{item.type==='report_impact'?`Report impact · ${String(item.summary.report_name??'BI report')}`:item.type==='nightly'?'Nightly profile updated':'Discovery completed'} · {item.readAt?'Earlier':'New'}</li>)}</ul>}</section>;
}

function NotificationPanel(props: { notifications: Notification[]; close: () => void; markRead: (id: string) => Promise<void> }) {
  const label=(item:Notification)=>item.type==='report_impact'?`Report impact · ${String(item.summary.report_name??'BI report')}`:item.type==='nightly'?'Nightly profile updated':'Discovery completed';
  return <aside className="notification-panel" aria-label="Notifications"><div className="page-heading"><h2>Notifications</h2><button aria-label="Close notifications" onClick={props.close}>×</button></div><h3>New</h3>{props.notifications.filter(item => !item.readAt).map(item => <button className="notification-item" key={item.notificationId} onClick={() => void props.markRead(item.notificationId)}>{label(item)}</button>)}<h3>Earlier</h3>{props.notifications.filter(item => item.readAt).map(item => <p className="muted" key={item.notificationId}>{label(item)}</p>)}</aside>;
}

type HubAdapterView = {product:string;connected:boolean;version:number;capabilities:string[]};
type MetricView = {metricId:string;name:string;description:string;unit:string;certified:boolean;adapterVersion:number};
const sampleFlowSpec={name:'Synthetic customer report handoff',sourceSnapshotIds:['00000000-0000-4000-8000-000000000001'],nodes:[{id:'read_source',kind:'read',capability:'metadata.read',inputs:{}},{id:'deliver_report',kind:'deliver',capability:'flowspec.handoff',inputs:{}}]};
function HubPage(props:{navigate:(path:string)=>void}){
 const [adapters,setAdapters]=useState<HubAdapterView[]>([]);const [metrics,setMetrics]=useState<MetricView[]>([]);const [results,setResults]=useState<Array<{runId:string;answer:{metric:string;bySource:Array<{value:number}>;evidence:Array<{content_hash:string;locator:string}>}}>>([]);const [error,setError]=useState('');
 async function refresh(){const [a,m]=await Promise.all([api<{adapters:HubAdapterView[]}>('/api/hub/adapters'),api<{metrics:MetricView[]}>('/api/semantics/metrics')]);setAdapters(a.adapters);setMetrics(m.metrics);}
 useEffect(()=>{void refresh().catch(reason=>setError(reason instanceof Error?reason.message:'Hub data could not be loaded.'));},[]);
 async function setConnection(adapter:HubAdapterView){try{await api(`/api/hub/adapters/${adapter.product}/${adapter.connected?'disconnect':'connect'}`,{method:'POST'});await refresh();}catch(reason){setError(reason instanceof Error?reason.message:'Adapter state could not be changed.');}}
 async function query(metricId:string){try{const result=await api<{runId:string;answer:MetricView & {metric:string;bySource:Array<{value:number}>;evidence:Array<{content_hash:string;locator:string}>}}>('/api/semantics/metrics/'+metricId+'/query',{method:'POST',headers:{'content-type':'application/json'},body:'{}'});setResults(value=>[result,...value]);}catch(reason){setError(reason instanceof Error?reason.message:'Certified metric query failed.');}}
 async function createFlow(){try{const result=await api<{flowspecId:string}>('/api/flowspecs',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(sampleFlowSpec)});props.navigate(`/flowspecs/${result.flowspecId}`);}catch(reason){setError(reason instanceof Error?reason.message:'FlowSpec could not be created.');}}
 return <section><h1>Hub integrations</h1><p>Certified metrics use version-pinned Semantics results and cited evidence. FlowSpec handoffs require a second-member approval.</p>{error&&<p role="alert" className="error">{error}</p>}<article><h2>Adapters</h2>{adapters.length===0?<p>No adapters are configured.</p>:adapters.map(item=><div key={item.product}><p>{item.product.replaceAll('_',' ')} · {item.connected?'Connected':'Disconnected'} · version {item.version}</p><button onClick={()=>void setConnection(item)}>{item.connected?`Disconnect ${item.product.replaceAll('_',' ')}`:`Connect ${item.product.replaceAll('_',' ')}`}</button></div>)}</article><article><h2>Certified metrics</h2>{metrics.length===0?<p>No certified metrics are available while Semantics is disconnected.</p>:metrics.map(metric=><div key={metric.metricId}><h3>{metric.name}</h3><p>{metric.description} · {metric.unit} · adapter version {metric.adapterVersion}</p><button onClick={()=>void query(metric.metricId)}>Query {metric.name}</button></div>)}{results.map(result=><div key={result.runId} className="assertion-row"><p>{result.answer.metric}: {result.answer.bySource[0]?.value}</p><p>Evidence: {result.answer.evidence[0]?.locator} · SHA-256 {result.answer.evidence[0]?.content_hash}</p></div>)}</article><article><h2>FlowSpec</h2><p>Build a synthetic report delivery for independent approval.</p><button onClick={()=>void createFlow()}>Create synthetic FlowSpec</button></article></section>;
}
function FlowSpecPage(props:{id:string}){
 const [versions,setVersions]=useState<Array<{version:number;payload:{name:string;nodes:Array<{id:string;kind:string;capability:string}>};subjectHash:string;sourceSnapshotIds:string[];policyVersion:string;approvalStatus:string;approvedBy:string|null;expiresAt:string;handoffId:string|null;handoffStatus:string|null;receiverRef:string|null}>>([]);const [message,setMessage]=useState('');const [error,setError]=useState('');
 async function refresh(){const data=await api<{versions:typeof versions}>(`/api/flowspecs/${props.id}`);setVersions(data.versions);}
 useEffect(()=>{void refresh().catch(reason=>setError(reason instanceof Error?reason.message:'FlowSpec could not be loaded.'));},[props.id]);
 async function approve(version:number){try{await api(`/api/flowspecs/${props.id}/approve`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({version})});setMessage(`Version ${version} approved.`);await refresh();}catch(reason){setError(reason instanceof Error?reason.message:'A different tenant member must approve this version.');}}
 async function handoff(version:number){try{const result=await api<{status:string;accepted:boolean}>(`/api/flowspecs/${props.id}/handoff`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({version})});setMessage(result.accepted?`Receiver confirmed version ${version}.`:`Receiver status is ${result.status}.`);await refresh();}catch(reason){setError(reason instanceof Error?reason.message:'Handoff could not be confirmed.');}}
 async function reconcile(item:typeof versions[number]){if(!item.handoffId)return;try{const result=await api<{status:string;accepted:boolean}>(`/api/flowspecs/${props.id}/handoff/${item.handoffId}`);setMessage(result.accepted?`Receiver confirmed version ${item.version}.`:`Receiver status is ${result.status}.`);await refresh();}catch(reason){setError(reason instanceof Error?reason.message:'Receiver status could not be checked.');}}
 async function revise(){try{const latest=versions.at(-1);if(!latest)return;const result=await api<{version:number}>(`/api/flowspecs/${props.id}/versions`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...sampleFlowSpec,name:`${latest.payload.name} revised`})});setMessage(`Version ${result.version} needs a new approval.`);await refresh();}catch(reason){setError(reason instanceof Error?reason.message:'New version could not be created.');}}
 return <section><h1>FlowSpec approval</h1><p>Each immutable version is approved by a different tenant member. Handoff acceptance appears only after receiver confirmation.</p>{error&&<p role="alert" className="error">{error}</p>}{message&&<p role="status">{message}</p>}{versions.map(item=><article key={item.version}><h2>{item.payload.name} · version {item.version}</h2><p>Subject hash {item.subjectHash}</p><p>Policy {item.policyVersion} · Source snapshots {item.sourceSnapshotIds.join(', ')}</p><ul>{item.payload.nodes.map(node=><li key={node.id}>{node.kind} · {node.capability}</li>)}</ul><p>{item.approvalStatus==='approved'?'Approved by another member':'Awaiting approval'}{item.approvedBy?` · ${item.approvedBy}`:''} · expires {new Date(item.expiresAt).toLocaleString()}</p>{item.handoffStatus&&<p>Data Studio status: {item.handoffStatus}{item.handoffStatus==='confirmed'||item.handoffStatus==='reconciled'?' · Accepted by receiver':''}{item.receiverRef?` · ${item.receiverRef}`:''}</p>}{item.approvalStatus==='pending'&&<button onClick={()=>void approve(item.version)}>Approve version {item.version}</button>}{item.approvalStatus==='approved'&&!item.handoffStatus&&<button onClick={()=>void handoff(item.version)}>Send version {item.version} to Data Studio</button>}{item.handoffId&&(item.handoffStatus==='pending'||item.handoffStatus==='unknown')&&<><button onClick={()=>void reconcile(item)}>Check Data Studio status</button>{item.handoffStatus==='unknown'&&<button onClick={()=>void handoff(item.version)}>Retry with the same key</button>}</>}</article>)}{versions.length>0&&<button onClick={()=>void revise()}>Create changed version</button>}</section>;
}

function App() {
  const [path, setPath] = useState(location.pathname + location.search);
  const [usage, setUsage] = useState<Usage | null>(null);
  const [connections, setConnections] = useState<Connection[]>([]);
  const [unauthorized, setUnauthorized] = useState(false);
  const [groups, setGroups] = useState<NavGroups>(loadGroups);
  const [profileOpen, setProfileOpen] = useState(false);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const [error, setError] = useState('');
  async function reloadConnections() { const result = await api<{ connections: Connection[] }>('/api/connections'); setConnections(result.connections); }
  async function reloadNotifications() { const result = await api<{ notifications: Notification[] }>('/api/notifications'); setNotifications(result.notifications); }
  useEffect(() => {
    void Promise.all([api<Usage>('/api/usage').then(setUsage), reloadConnections()]).catch(reason => {
      if (reason instanceof Error && reason.message === 'unauthorized') setUnauthorized(true);
      else setError('Workspace data could not be loaded.');
    });
  }, []);
  useEffect(() => { try { localStorage.setItem('nav-workspace', String(groups.workspace)); localStorage.setItem('nav-platform', String(groups.platform)); } catch { /* Navigation still works when storage is disabled. */ } }, [groups]);
  useEffect(() => { const pop = () => setPath(location.pathname + location.search); addEventListener('popstate', pop); return () => removeEventListener('popstate', pop); }, []);
  if (path.startsWith('/login') || unauthorized) return <Login />;
  const navigate = (url: string) => { history.pushState({}, '', url); setPath(url); setError(''); };
  const toggle = (group: keyof NavGroups) => setGroups(value => ({ ...value, [group]: !value[group] }));
  async function signOut() { await fetch('/api/auth/logout', { method: 'POST' }); location.assign('/login'); }
  async function markRead(id: string) { await api(`/api/notifications/${id}/read`, { method: 'POST' }); await reloadNotifications(); }
  const currentConnection = new URLSearchParams(path.split('?')[1] ?? '').get('connection') ?? path.split('/')[2];
  let page: React.ReactNode;
  if (path.startsWith('/usage')) page = <section><h1>Usage</h1><p>Counts are derived from activity events for this billing period.</p><div className="cards"><article><span>Active users</span><strong>{usage?.active_users ?? 0}</strong></article>{Object.entries(usage?.active_connectors.by_type ?? {}).map(([type, count]) => <article key={type}><span>Active {type.replaceAll('_', ' ')} connectors</span><strong>{count}</strong></article>)}</div></section>;
  else if (path.startsWith('/connectors')) page = <ConnectorsPage connections={connections} reload={reloadConnections} navigate={navigate} />;
  else if (path.startsWith('/profile/')) page = <ProfilePage connectionId={currentConnection ?? ''} navigate={navigate} />;
  else if (path.startsWith('/dictionary')) page = currentConnection ? <DictionaryPage connectionId={currentConnection} /> : <section><h1>Dictionary</h1><p>Choose a connector to browse its Dictionary.</p>{connections.filter(connection => connection.status === 'active').map(connection => <button key={connection.connectionId} onClick={() => navigate(`/dictionary?connection=${connection.connectionId}`)}>{connection.connectorType.replaceAll('_', ' ')}</button>)}</section>;
  else if (path.startsWith('/controls')) page = currentConnection ? <ControlsPage connectionId={currentConnection} /> : <section><h1>Controls</h1><p>Choose a connector to manage its scope.</p>{connections.filter(connection => connection.status === 'active').map(connection => <button key={connection.connectionId} onClick={() => navigate(`/controls?connection=${connection.connectionId}`)}>{connection.connectorType.replaceAll('_', ' ')}</button>)}</section>;
  else if (path.startsWith('/er') || path.startsWith('/lineage') || path.startsWith('/bi-reports')) page = <LineageWorkspace path={path} navigate={navigate} />;
  else if (path.startsWith('/approval-matrix')) page = <ApprovalMatrix />;
  else if (path.startsWith('/reports')) page = <ReportsPage />;
  else if (path.startsWith('/hub')) page = <HubPage navigate={url=>{history.pushState({},'',url);setPath(url);}} />;
  else if (path.startsWith('/flowspecs/')) page = <FlowSpecPage id={path.split('/')[2]??''} />;
  else if (path.startsWith('/agents') || path.startsWith('/my-agent')) page = <AgentsPage />;
  else if(path.startsWith('/runs/'))page=<AnalyticWorkspace connections={connections} navigate={navigate} runId={path.split('/')[2]}/>;
  else page = <AnalyticWorkspace connections={connections} navigate={navigate} />;

  return <div className="app"><aside>
    <div className="brand"><span className="brandmark">S</span><b>Scale Insyght</b></div>
    <button className="new-chat" disabled aria-label="New chat available in a later phase">＋ New chat</button>
    <nav aria-label="Main navigation">
      <button className="section-toggle" aria-expanded={groups.workspace} onClick={() => toggle('workspace')}>WORKSPACE <span aria-hidden="true">{groups.workspace ? '⌄' : '›'}</span></button>
      {groups.workspace && <div className="nav-items"><a href="/" aria-current={path === '/' ? 'page' : undefined} onClick={event => { event.preventDefault(); navigate('/'); }}>⌂ <span>Home</span></a><a href="/connectors" aria-current={path.startsWith('/connectors') ? 'page' : undefined} onClick={event => { event.preventDefault(); navigate('/connectors'); }}>◫ <span>Connectors</span></a><a href="/dictionary" aria-current={path.startsWith('/dictionary') ? 'page' : undefined} onClick={event => { event.preventDefault(); navigate('/dictionary'); }}>▤ <span>Dictionary</span></a><a href="/lineage" aria-current={path.startsWith('/lineage') || path.startsWith('/er') ? 'page' : undefined} onClick={event => { event.preventDefault(); navigate('/lineage'); }}>⌘ <span>Lineage</span></a><a href="/reports" aria-current={path.startsWith('/reports')?'page':undefined} onClick={event=>{event.preventDefault();navigate('/reports');}}>▧ <span>Reports</span></a></div>}
      <button className="section-toggle" aria-expanded={groups.platform} onClick={() => toggle('platform')}>PLATFORM <span aria-hidden="true">{groups.platform ? '⌄' : '›'}</span></button>
      {groups.platform && <div className="nav-items"><a href="/agents" onClick={event=>{event.preventDefault();navigate('/agents');}}>◉ <span>Agents</span></a><a href="/hub" onClick={event=>{event.preventDefault();navigate('/hub');}}>◈ <span>Hub integrations</span></a><a href="/bi-reports" onClick={event=>{event.preventDefault();navigate('/bi-reports');}}>▧ <span>BI reports</span></a><a href="/approval-matrix" onClick={event => { event.preventDefault(); navigate('/approval-matrix'); }}>✓ <span>Approval matrix</span></a><a href="/controls" onClick={event => { event.preventDefault(); navigate('/controls'); }}>⚙ <span>Controls</span></a></div>}
    </nav>
    <div className="recent"><p>RECENT</p><span>No recent conversations</span></div>
    <div className="profile"><button aria-haspopup="menu" aria-expanded={profileOpen} onClick={() => setProfileOpen(value => !value)}><span className="avatar">A</span><span>Workspace profile</span><span aria-hidden="true">⋯</span></button>{profileOpen && <div role="menu"><button role="menuitem" onClick={() => navigate('/usage')}>Usage</button><button role="menuitem" onClick={signOut}>Sign out</button></div>}</div>
  </aside><main><header><span>Analytic mode · read-only</span><button aria-label="Notifications" title="Notifications" onClick={() => { setNotificationsOpen(value => !value); if (!notificationsOpen) void reloadNotifications(); }}>♧ {notifications.filter(item => !item.readAt).length || ''}</button></header>{error && <p className="error" role="alert">{error}</p>}{page}{notificationsOpen && <NotificationPanel notifications={notifications} close={() => setNotificationsOpen(false)} markRead={markRead} />}</main></div>;
}

createRoot(document.getElementById('root')!).render(<App />);
